CREATE DATABASE uuiddemo;
\c uuiddemo

CREATE TABLE orders (
    order_id    uuid PRIMARY KEY DEFAULT uuidv7(),
    customer    text NOT NULL,
    amount      numeric(10,2) NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT clock_timestamp()
);

INSERT INTO orders (customer, amount) VALUES ('Asha', 1250.00);
SELECT pg_sleep(0.01);
INSERT INTO orders (customer, amount) VALUES ('Ravi', 499.50);
SELECT pg_sleep(0.01);
INSERT INTO orders (customer, amount) VALUES ('Meena', 3200.00);
SELECT pg_sleep(0.01);
INSERT INTO orders (customer, amount) VALUES ('John', 75.25)
RETURNING order_id;

SELECT uuidv7() AS id,
       uuid_extract_version(uuidv7()) AS v7,
       uuid_extract_version(uuidv4()) AS v4;

CREATE TABLE orders_v4 (order_id uuid PRIMARY KEY DEFAULT uuidv4(),
                        amount numeric(10,2));
CREATE TABLE orders_v7 (order_id uuid PRIMARY KEY DEFAULT uuidv7(),
                        amount numeric(10,2));

INSERT INTO orders_v4 (amount)
SELECT (random()*5000)::numeric(10,2) FROM generate_series(1, 1000000);

INSERT INTO orders_v7 (amount)
SELECT (random()*5000)::numeric(10,2) FROM generate_series(1, 1000000);

CREATE TABLE customers (
    customer_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name        text
);
INSERT INTO customers (name) VALUES ('Asha'), ('Ravi');

ALTER TABLE customers ALTER COLUMN customer_id SET DEFAULT uuidv7();

INSERT INTO customers (name) VALUES ('Meena');

SELECT name, customer_id, uuid_extract_version(customer_id) AS version
  FROM customers;

EXPLAIN (COSTS OFF)
SELECT count(*) FROM orders_v7
 WHERE uuid_extract_timestamp(order_id) >= now() - interval '1 hour';

